    // === Вспомогательная функция: получить целевой ник ===
    function getTargetNick() {
        if (TARGET_NICK) return TARGET_NICK;

        // Ищем .css-rxxlm3 на странице (ваш ник в интерфейсе)
        const nickEl = document.querySelector('.css-rxxlm3');
        if (nickEl && nickEl.textContent) {
            const parts = nickEl.textContent.trim().split(' ');
            const nick = parts[parts.length - 1];
            return nick;
        }
        return null;
    }

    // === ЛОГИКА: добавляем/убираем классы в зависимости от условий ===
    function applyConditionalClass() {
        const containers = document.querySelectorAll('.css-te6xsk');
        const targetNick = getTargetNick();

        containers.forEach((container) => {
            // --- Условие 1: .css-jd7l13 → has-battle-info ---
            try {
                const hasBattleInfo = container.querySelector('.css-jd7l13');
                const hasBattleClass = container.classList.contains('has-battle-info');

                if (hasBattleInfo && !hasBattleClass) {
                    container.classList.add('has-battle-info');
                } else if (!hasBattleInfo && hasBattleClass) {
                    container.classList.remove('has-battle-info');
                }

                // --- Условие 2: ник во ВТОРОМ .css-o2wsxr → has-my-nick ---
                if (targetNick) {
                    // Находим ВСЕ .css-o2wsxr внутри этого контейнера
                    const playerContainers = container.querySelectorAll('.css-o2wsxr');

                    // Пробуем ВТОРОЙ (индекс 1), если нет - ищем по содержимому
                    let secondPlayer = playerContainers[1];

                    if (secondPlayer) {
                        const hasMyNick = secondPlayer.textContent.includes(targetNick);
                        const hasMyNickClass = container.classList.contains('has-my-nick');

                        if (hasMyNick && !hasMyNickClass) {
                            container.classList.add('has-my-nick');
                        } else if (!hasMyNick && hasMyNickClass) {
                            container.classList.remove('has-my-nick');
                        }
                    }
                }
            } catch(err) {
                // Если игра удалила элемент до обновления классов — игнорируем
            }
        });
    }
	
	const scrollbarRegistry = new Map();

    function createScrollbarElements(container) {
		const containerId = container.id || 'chat-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
		container.id = containerId;
		
        const scrollbarTrack = document.createElement('div');
		scrollbarTrack.className = 'custom-scrollbar-track';
		scrollbarTrack.id = 'track-' + containerId;
		scrollbarTrack.dataset.parentId = containerId;
		
		
        scrollbarTrack.style.cssText = `
            position: absolute;
            top: 0.2rem;
            right: 0.2rem;
            width: calc(var(--browser-zoom-factor) * 0.16vw);
			height: calc(100% - 0.4rem);
			border: calc(var(--browser-zoom-factor) * 0.08vw) solid rgba(0, 215, 0, 0.3);
            border-radius: 2px;
            z-index: 0;
            pointer-events: auto;
        `;
		
		

        const scrollbarThumb = document.createElement('div');
		
        scrollbarThumb.className = 'custom-scrollbar-thumb';
		scrollbarThumb.id = 'thumb-' + containerId; // Привязка по ID
		scrollbarThumb.dataset.parentId = containerId;
	
        scrollbarThumb.style.cssText = `
            width: 62%;
            margin: 0 0.06rem;
            background: rgb(10, 228, 0);
            border-radius: 2px;
            cursor: pointer;
            min-height: 20px;
            position: absolute;
            top: 0;
            left: 0;
            pointer-events: auto;
        `;


        scrollbarTrack.appendChild(scrollbarThumb);
        container.appendChild(scrollbarTrack);
		
		
		// Сохраняем ссылки в хранилище
		scrollbarRegistry.set(container, { track: scrollbarTrack, thumb: scrollbarThumb });
		return { track: scrollbarTrack, thumb: scrollbarThumb, id: containerId };
    }

    function initCustomScrollbar(container) {
		if (container.dataset.customScrollbar === 'true') return; 
		
		const { track, thumb, id } = createScrollbarElements(container);
		container.dataset.customScrollbar = 'true';
		
		function updateScrollbar() {
			if (!track || !thumb) return;
			
			const scrollHeight = container.scrollHeight;
			const clientHeight = container.clientHeight;
			const scrollTop = container.scrollTop;

			if (scrollHeight <= clientHeight) {
				track.style.opacity = '0';
				track.style.pointerEvents = 'none';
				return;
			}

			track.style.opacity = '1';
			track.style.pointerEvents = 'auto';

			const thumbHeight = Math.max(20, (clientHeight / scrollHeight) * clientHeight);
			const thumbPosition = (scrollTop / (scrollHeight - clientHeight)) * (clientHeight - thumbHeight);

			thumb.style.height = thumbHeight + 'px';
			thumb.style.transform = `translateY(${thumbPosition}px)`;
		}

		container.addEventListener('wheel', (e) => {
			e.preventDefault();
			container.scrollTop += e.deltaY;
			updateScrollbar();
		}, { passive: false });

		let isDragging = false;
		let startY = 0;
		let startScrollTop = 0;
		let draggingContainer = null;

		thumb.addEventListener('mousedown', (e) => {
			isDragging = true;
			startY = e.clientY;
			startScrollTop = container.scrollTop;
			draggingContainer = container;
			thumb.style.background = 'rgb(89, 255, 50)';
			e.preventDefault();
			e.stopPropagation();
		});

		document.addEventListener('mousemove', (e) => {
			if (!isDragging || !draggingContainer) return;
			
			const deltaY = e.clientY - startY;
			const scrollHeight = draggingContainer.scrollHeight;
			const clientHeight = draggingContainer.clientHeight;
			const thumbHeight = parseFloat(thumb.style.height) || 20;

			const scrollRatio = (scrollHeight - clientHeight) / (clientHeight - thumbHeight);
			draggingContainer.scrollTop = startScrollTop + (deltaY * scrollRatio);
			
			updateScrollbar();
		});

		document.addEventListener('mouseup', () => {
			if (isDragging) {
				isDragging = false;
				thumb.style.background = 'rgb(23, 255, 1)';
			}
		});

		const resizeObserver = new ResizeObserver(() => {
			updateScrollbar();
		});
		
		resizeObserver.observe(container);

		window.addEventListener('resize', updateScrollbar);
	}

    // === Запуск функций ===
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            applyConditionalClass();
        });
    } else {
        applyConditionalClass();
    }

    // === MutationObserver ===
    let checkTimeout = null;
    const observer = new MutationObserver((mutations) => {
        let shouldCheck = false;
        for (const mutation of mutations) {
            if (mutation.addedNodes.length || mutation.removedNodes.length || mutation.type === 'characterData') {
                shouldCheck = true;
                break;
            }
        }
        if (shouldCheck) {
            if (checkTimeout) clearTimeout(checkTimeout);
            checkTimeout = setTimeout(() => {
                try {
                    applyConditionalClass();
                } catch(e) {}
            }, 10);
        }
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true
    });
	
	// === ГЛОБАЛЬНАЯ ФУНКЦИЯ ПОЛУЧЕНИЯ ZOOMA ===
	function getCurrentZoom() {
		const w = window.innerWidth;
		const h = window.innerHeight;
		
		const div = document.createElement('div');
		div.style.width = '100vw';
		div.style.height = '100vh';
		div.style.margin = '0';
		div.style.padding = '0';
		div.style.border = 'none';
		document.body.appendChild(div);
		
		let ratio = 1;
		let realRatio = window.outerWidth / parseInt(document.defaultView.getComputedStyle(div).width);
		
		if (realRatio < 0.26 && realRatio > 0.24) { ratio = 0.75; }
		else if (realRatio < 0.34 && realRatio > 0.32) { ratio = 0.78; }
		else if (realRatio < 0.51 && realRatio > 0.49) { ratio = 0.83; }
		else if (realRatio < 0.67 && realRatio > 0.65) { ratio = 0.87; }
		else if (realRatio < 0.76 && realRatio > 0.74) { ratio = 0.9; }
		else if (realRatio < 0.81 && realRatio > 0.79) { ratio = 0.93; }
		else if (realRatio < 0.91 && realRatio > 0.89) { ratio = 0.96; }
		else if (realRatio < 1.11 && realRatio > 1.09) { ratio = 1.05; }
		else if (realRatio < 1.26 && realRatio > 1.24) { ratio = 1.08; }
		else if (realRatio < 1.51 && realRatio > 1.49) { ratio = 1.11; }
		else if (realRatio < 1.76 && realRatio > 1.74) { ratio = 1.14; }
		else if (realRatio < 2.01 && realRatio > 1.99) { ratio = 1.17; }
		else if (realRatio < 2.51 && realRatio > 2.49) { ratio = 1.2; }
		else if (realRatio < 3.01 && realRatio > 2.99) { ratio = 1.23; }
		else if (realRatio < 4.01 && realRatio > 3.99) { ratio = 1.26; }
		else if (realRatio < 5.01 && realRatio > 4.99) { ratio = 1.3; }
		
		document.body.removeChild(div);
		return ratio;
	}

	// === ОБНОВЛЕНИЕ CSS ПЕРЕМЕННЫХ ===
	function updateCSSZoomVariable(zoomFactor) {
		document.documentElement.style.setProperty('--browser-zoom-factor', zoomFactor);
	}

	function updateFontBasedOnZoom() {
		const baseValue = 1.48148;
		const zoomFactor = getCurrentZoom();
		const vhUnit = window.innerHeight / 100;
		const vwUnit = window.innerWidth / 100;
		
		const calculatedSize = Math.max(
			Math.min(baseValue * zoomFactor * vhUnit, vwUnit),
			3
		);
		
		updateCSSZoomVariable(zoomFactor);
		
		document.documentElement.style.fontSize = `${calculatedSize}px`;
		
	}

	updateFontBasedOnZoom();
	window.addEventListener('resize', updateFontBasedOnZoom);

	// === ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ ДЛЯ УПРАВЛЕНИЯ ===
	window.__SELECTED_MIN_RANK__ = 1;
	window.__SELECTED_MAX_RANK__ = 31;
	let _isDragging = false;
	let _startX = 0;
	let _currentDragRank = 1;

	// === MAP КЛАССОВ ===
	const classMap = {
		'.css-19k7i50': 'rank-selector-container',
		'.css-xsyx1f': 'rank-progress',
		'.css-qtzrfv': 'rank-progress',
		'.css-1ewhe6d': 'rank-progress',
		'.css-1g5n39': 'rank-item',
		'.css-13q915e': 'drag-handle-left',
		'.css-vheepe': 'drag-handle-right'
	};

	// === ФУНКЦИЯ СОЗДАНИЯ И РАЗМЕЩЕНИЯ CLONE ===
	function createRankSelector() {
		const parentContainer = document.querySelector('.css-rbhnh7');
		const originalContainer = document.querySelector('.css-19k7i50');
		
		if (!parentContainer || !originalContainer) {
			console.warn('[Debug Error] Контейнеры не найдены!');
			return null;
		}
		
		// Удаляем старый клон если существует
		const existingClone = document.querySelector('#rank-selector-cloned');
		if (existingClone) existingClone.remove();
		
		// Клонируем весь фрагмент включая inline-стили
		const clonedContainer = originalContainer.cloneNode(true);
		
		// Переименовываем классы
		Object.entries(classMap).forEach(([oldClass, newClass]) => {
			const foundElements = clonedContainer.querySelectorAll(oldClass);
			foundElements.forEach(el => {
				el.classList.remove(...el.classList);
				el.classList.add(newClass);
			});
		});
		
		// === ВОССТАНАВЛИВАЕМ ОРИГИНАЛЬНЫЕ СТИЛИ ===
		clonedContainer.id = 'rank-selector-cloned';
		clonedContainer.removeAttribute('style');
		
		// Добавляем только новые уникальные свойства для селектора
		clonedContainer.style.position = 'relative';
		clonedContainer.style.pointerEvents = 'auto';
		clonedContainer.style.width = '100%';
		
		// === СКРЫВАЕМ ОРГАНИАЛ ===
		originalContainer.style.display = 'none';
		originalContainer.style.visibility = 'hidden';
		originalContainer.style.pointerEvents = 'none';
		originalContainer.style.position = 'absolute';
		originalContainer.style.opacity = '0';
		
		// Вставляем клон ВНУТРИ родителя
		const afterOriginal = document.createElement('div');
		parentContainer.insertBefore(afterOriginal, originalContainer.nextSibling);
		parentContainer.insertBefore(clonedContainer, afterOriginal);
		
		return clonedContainer;
	}
	
	// === НАХОДИМ МАКСИМАЛЬНЫЙ РАНГ ИЗ ЗАГОЛОВКА ===
	function getMaxRankFromHeader() {
		const header = document.querySelector('.css-iyaxzc');
		
		if (!header) return 1; // Если нет заголовка — 31 ранг доступен
		
		const headerImg = header.querySelector('img');
		
		if (!headerImg || !headerImg.src) return 1;
		
		// Извлекаем номер из пути /images/XX.xxxxxx.webp
		const match = headerImg.src.match(/\/images\/(\d+)\./);
		
		if (!match || !match[1]) return 1;
		
		const rankNum = parseInt(match[1]);
		
		return rankNum;
	}

	// === НАСТРОЙКА HANDLES ДЛЯ DRAGGING ЧЕРЕЗ .RANK-ITEM + КЛИК ВЕСЬ КОНТЕЙНЕР ===
	function setupDragHandles(container) {
		const handleLeftDrag = container.querySelector('.drag-handle-left');
		const handleRightDrag = container.querySelector('.drag-handle-right');
		const handleLeft = handleLeftDrag?.closest('.rank-item');
		const handleRight = handleRightDrag?.closest('.rank-item');
		const progressBar = container.querySelector('.rank-progress');
		const rankItems = Array.from(container.querySelectorAll('.rank-item'));
		
		let startX = 0;
		let activeHandle = null; // Текущий активный хендл
		
		// === ДЕФАЛТНЫЕ ЗНАЧЕНИЯ ВМЕСТО NULL! ===
		let selectionStart = getMaxRankFromHeader(); // Левый хендл по умолчанию в начале
		let selectionEnd = 30;   // Правый хендл по умолчанию в конце
		
		// === МАКСИМАЛЬНЫЙ РАЗРЕШЁННЫЙ ИНДЕКС (из заголовка!) ===
		let maxAllowedIndex = getMaxRankFromHeader() - 1; // Индекс = ранг - 1
		
		// === НАХОДИМ РАНГОВЫЕ ЭЛЕМЕНТЫ ВНУТРЯ HANDLE-LIGHT И HANDLE-RIGHT ===
		let handleLeftRank = null;    // Элемент .rank-N внутри handleLeft
		let handleRightRank = null;   // Элемент .rank-N внутри handleRight
		
		if (handleLeft) {
			// Находим первый child который имеет класс rank-XX
			handleLeftRank = Array.from(handleLeft.children).find(child => /rank-\d+/.test(child.className));
		}
		
		if (handleRight) {
			// Находим первый child который имеет класс rank-XX
			handleRightRank = Array.from(handleRight.children).find(child => /rank-\d+/.test(child.className));
		}
		
		
		
		
		// === ФУНКЦИЯ ОБНОВЛЕНИЯ КЛАССА РАНГА ===
		function updateRankClass(element, newRankIndex) {
			if (!element) return;
			
			// Удаляем старый класс rank-XX
			element.classList.forEach(cls => {
				if (/^rank-\d+$/.test(cls)) {
					element.classList.remove(cls);
				}
			});
			
			// Добавляем новый класс rank-{ранг}
			const rankNum = newRankIndex + 1;
			element.classList.add(`rank-${rankNum}`);
			
		}
		
		// === ФУНКЦИЯ УПРАВЛЕНИЯ ВИДИМОСТЬЮ РАНГОВ ===
		function updateRankVisibility() {
			// Если индексы равны — скрываем правый элемент
			if (selectionStart === selectionEnd && handleRightRank) {
				handleRightRank.style.display = 'none';
				
				// Показываем левый элемент
				if (handleLeftRank) {
					handleLeftRank.style.display = '';
				}
				
			} 
			// Если индексы разные — показываем оба
			else if (selectionStart !== selectionEnd) {
				if (handleLeftRank) handleLeftRank.style.display = '';
				if (handleRightRank) handleRightRank.style.display = '';
				
			}
		}
		
		// === ОБНОВЛЕНИЕ INSET ЧЕРЕЗ REAL VW + ZOOM FACTOR ===
		function updateProgressBarInset() {
			const browserZoom = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--browser-zoom-factor')) || 1;
			const zoomMultiplier = Math.round(browserZoom * 100) / 100;
			
			// Индексы должны быть от 0 до 30
			selectionStart = Math.max(0, Math.min(maxAllowedIndex, selectionStart));
			selectionEnd = Math.max(0, Math.max(maxAllowedIndex, selectionEnd)); 
			
			// Убеждаемся что left <= right для корректной работы
			if (selectionStart > selectionEnd) {
				[selectionStart, selectionEnd] = [selectionEnd, selectionStart];
			}
			// Обновляем классы рангов
			if (handleLeftRank) updateRankClass(handleLeftRank, selectionStart);
			if (handleRightRank) updateRankClass(handleRightRank, selectionEnd);
			
			// Обновляем видимость
			updateRankVisibility();
			
			
			// inset: top | right | bottom | left
			progressBar.style.setProperty('inset', 
				`0.1875rem calc(${zoomMultiplier} * ${30 - selectionEnd}vw) 0.1875rem calc(${zoomMultiplier} * ${selectionStart}vw)`,
				'important'
			);
		}
		
		function updateSelectionVisual() {
			updateProgressBarInset();
		}
		
		function finalizeSelection() {
			updateSelectionVisual();
			
			window.__SELECTED_MIN_RANK__ = Math.min(selectionStart, selectionEnd) + 1;
			window.__SELECTED_MAX_RANK__ = Math.max(selectionStart, selectionEnd) + 1;
			
		}
		
		// === ФУНКЦИЯ ОПРЕДЕЛЕНИЯ КАКОЙ ХЕНДЛ ДВИГАТЬ ПРИ КЛИКЕ ===
		function determineHandleToMove(clickedIndex) {
			// Получаем текущие позиции progress bars
			const startPct = selectionStart; // 0-30
			const endPct = 30 - selectionEnd; // тоже 0-30
			
			// Если прогресс бара нет или он невиден
			if (!progressBar) return null;
			
			const rect = container.getBoundingClientRect();
			const totalWidth = rect.width;
			const itemWidth = totalWidth / 31;
			
			// Вычисляем реальную позицию прогресс бара в пикселях
			const progressStartX = startPct * itemWidth;
			const progressEndX = totalWidth - endPct * itemWidth;
			const progressCenter = (progressStartX + progressEndX) / 2;
			
			// Кликал левее центра прогресса — двигаем левую сторону
			if (clickedIndex < progressStartX / itemWidth) {
				return 'left';
			}
			// Кликал правее центра прогресса — двигаем правую сторону
			else if (clickedIndex >= progressEndX / itemWidth) {
				return 'right';
			}
			// Кликал внутри прогресса — двигаем ближайший край
			else {
				const distToStart = clickedIndex - startPct;
				const distToEnd = endPct - clickedIndex;
				
				if (Math.abs(distToStart) <= Math.abs(distToEnd)) {
					return 'left';
				} else {
					return 'right';
				}
			}
		}
		
		// === КЛИК ВО ВСЕМ КОНТЕЙНЕРЕ — ЛЕВАЯ ИЛИ ПРАВАЯ СТОРОНА ===
		container.addEventListener('mousedown', (e) => {
			e.preventDefault();
			e.stopPropagation();
			
			// Не переключаем если уже тянем через handleLeft или handleRight
			if (_isDragging && activeHandle === 'left') return;
			if (_isDragging && activeHandle === 'right') return;
			
			const rect = container.getBoundingClientRect();
			const relativeX = e.clientX - rect.left;
			const itemWidth = rect.width / 31;
			const clickedIndex = Math.min(Math.max(0, Math.floor(relativeX / itemWidth)), 30);
			
			activeHandle = determineHandleToMove(clickedIndex);
			
			if (activeHandle === 'left') {
				selectionStart = clickedIndex;
			} else if (activeHandle === 'right') {
				selectionEnd = clickedIndex;
			}
			
			if (activeHandle) {
				_isDragging = true;
				startX = e.clientX;
				progressBar.style.transition = 'none';
				
			}
		}, { passive: false });
		
		container.addEventListener('touchstart', (e) => {
			e.preventDefault();
			e.stopPropagation();
			
			const touch = e.touches[0];
			const rect = container.getBoundingClientRect();
			const relativeX = touch.clientX - rect.left;
			const itemWidth = rect.width / 31;
			const clickedIndex = Math.min(Math.max(0, Math.floor(relativeX / itemWidth)), 30);
			
			activeHandle = determineHandleToMove(clickedIndex);
			
			if (activeHandle === 'left') {
				selectionStart = clickedIndex;
			} else if (activeHandle === 'right') {
				selectionEnd = clickedIndex;
			}
			
			if (activeHandle) {
				_isDragging = true;
				startX = touch.clientX;
				progressBar.style.transition = 'none';
				
			}
		}, { passive: false });
		
		// === ЛЕВАЯ РУЧКА ИДЕТ ЧЕРЕЗ RANK-ITEM ===
		if (handleLeft) {
			handleLeft.style.cursor = 'ew-resize !important';
			handleLeft.style.pointerEvents = 'auto';
			
			// Добавляем слушатели на саму левую стрелку (для обратного совместимости)
			handleLeft.addEventListener('mousedown', (e) => {
				e.preventDefault();
				e.stopPropagation();
				
				activeHandle = 'left';
				_isDragging = true;
				startX = e.clientX;
				
				const rect = container.getBoundingClientRect();
				const relativeX = e.clientX - rect.left;
				const itemWidth = rect.width / 31;
				selectionStart = Math.floor(relativeX / itemWidth);
				
				handleLeft.style.cursor = 'ew-resize';
				progressBar.style.transition = 'none';
			}, { passive: false });
			
			handleLeft.addEventListener('touchstart', (e) => {
				e.preventDefault();
				e.stopPropagation();
				
				activeHandle = 'left';
				_isDragging = true;
				startX = e.touches[0].clientX;
				
				const rect = container.getBoundingClientRect();
				const relativeX = e.touches[0].clientX - rect.left;
				const itemWidth = rect.width / 31;
				selectionStart = Math.floor(relativeX / itemWidth);
				
				progressBar.style.transition = 'none';
			}, { passive: false });
		}
		
		// === ПРАВАЯ РУЧКА ИДЕТ ЧЕРЕЗ RANK-ITEM ===
		if (handleRight) {
			handleRight.style.cursor = 'ew-resize !important';
			handleRight.style.pointerEvents = 'auto';
			
			// Добавляем слушатели на саму правую стрелку (для обратного совместимости)
			handleRight.addEventListener('mousedown', (e) => {
				e.preventDefault();
				e.stopPropagation();
				
				activeHandle = 'right';
				_isDragging = true;
				startX = e.clientX;
				
				const rect = container.getBoundingClientRect();
				const relativeX = e.clientX - rect.left;
				const itemWidth = rect.width / 31;
				selectionEnd = Math.floor(relativeX / itemWidth);
				
				handleRight.style.cursor = 'ew-resize';
				progressBar.style.transition = 'none';
			}, { passive: false });
			
			handleRight.addEventListener('touchstart', (e) => {
				e.preventDefault();
				e.stopPropagation();
				
				activeHandle = 'right';
				_isDragging = true;
				startX = e.touches[0].clientX;
				
				const rect = container.getBoundingClientRect();
				const relativeX = e.touches[0].clientX - rect.left;
				const itemWidth = rect.width / 31;
				selectionEnd = Math.floor(relativeX / itemWidth);
				
				progressBar.style.transition = 'none';
			}, { passive: false });
		}
		
		// === ОБЩЕЕ ДВИЖЕНИЕ МЫШИ/ТАЧА ===
		document.addEventListener('mousemove', (e) => {
			if (!_isDragging || !activeHandle) return;
			
			const rect = container.getBoundingClientRect();
			const relativeX = e.clientX - rect.left;
			const itemWidth = rect.width / 31;
			const index = Math.min(Math.max(0, Math.floor(relativeX / itemWidth)), 30);
			
			if (activeHandle === 'left') {
				selectionStart = index;
			} else if (activeHandle === 'right') {
				selectionEnd = index;
			}
			
			updateSelectionVisual();
		}, { passive: false });
		
		document.addEventListener('touchmove', (e) => {
			if (!_isDragging || !activeHandle) return;
			
			const rect = container.getBoundingClientRect();
			const relativeX = e.touches[0].clientX - rect.left;
			const itemWidth = rect.width / 31;
			const index = Math.min(Math.max(0, Math.floor(relativeX / itemWidth)), 30);
			
			if (activeHandle === 'left') {
				selectionStart = index;
			} else if (activeHandle === 'right') {
				selectionEnd = index;
			}
			
			updateSelectionVisual();
		}, { passive: false });
		
		// === ЗАВЕРШЕНИЕ ===
		document.addEventListener('mouseup', (e) => {
			if (_isDragging && activeHandle) {
				_isDragging = false;
				activeHandle = null; // Сброс активного хендла
				
				if (handleLeft) {
					selectionStart = Math.max(0, Math.min(maxAllowedIndex, selectionStart));
				}
				if (handleRight) {
					selectionEnd = Math.max(0, Math.max(maxAllowedIndex, selectionEnd));
				}
				
				setTimeout(() => {
					progressBar.style.transition = 'inset 0.1s ease-out';
				}, 10);
				
				finalizeSelection();
				
				if (handleLeft) handleLeft.style.cursor = 'ew-resize !important';
				if (handleRight) handleRight.style.cursor = 'ew-resize !important';
			}
		}, { passive: false });
		
		document.addEventListener('touchend', () => {
			if (_isDragging && activeHandle) {
				_isDragging = false;
				activeHandle = null;
				
				if (handleLeft) {
					selectionStart = Math.max(0, Math.min(maxAllowedIndex, selectionStart));
				}
				if (handleRight) {
					selectionEnd = Math.max(0, Math.max(maxAllowedIndex, selectionEnd));
				}
				
				setTimeout(() => {
					progressBar.style.transition = 'inset 0.1s ease-out';
				}, 10);
				
				finalizeSelection();
			}
		}, { passive: false });
		
		finalizeSelection();
	}
	
	
	function removeEmptyDivsInContainer() {
		const container = document.querySelector('.css-rbhnh7');
		
		if (!container) {
			console.warn('[Remove Bare Divs] Container .css-rbhnh7 not found!');
			return;
		}
		
		let removedCount = 0;
		const removedDivs = [];
		
		// Получаем всех прямых детей-дів внутри контейнера
		const allDivs = Array.from(container.querySelectorAll('div'));
		
		
		// Проверяем и удаляем только пустые
		allDivs.forEach(div => {
			// Получаем список всех атрибутов элемента (кроме style который может быть автогенерируемым)
			const attributesArray = Array.from(div.attributes).filter(attr => 
				attr.name !== 'style' &&           // Исключаем inline стили
				attr.name !== 'id'                 // Иногда id генерируется автоматически
			);
			
			// Проверка на "очень пустой" div:
			const isBareEmpty = 
				div.childNodes.length === 0 &&                      // Нет текстовых узлов
				div.textContent.trim().length === 0 &&              // Нет текста/пробелов
				div.childElementCount === 0 &&                      // Нет дочерних элементов
				div.classList.length === 0 &&                       // Нет классов ✅
				div.hasAttribute('class') === false &&              // Нет атрибута class ✅
				!div.id &&                                          // Нет ID (опционально)
				attributesArray.length === 0;                       // Нет других атрибутов
				
			if (isBareEmpty) {

				div.remove();
				removedCount++;
				removedDivs.push({ index: div.parentElement?.children.length, reason: 'bare-empty' });
			}
		});
		
		
		// Финальная проверка
		const remainingDivs = container.querySelectorAll('div');
		
		return removedCount;
	}

	// === ГЛОБАЛЬНАЯ ПЕРЕМЕННАЯ ДЛЯ АКТИВНЫХ ЧЕКБОКСОВ ===
	window.__ACTIVE_CHECKBOXES__ = [];

	// === КАРТА НАЗВАНИЙ ЧЕКБОКСОВ ===
	const CHECKBOX_NAME_MAP = {
		'Закрытая битва': 'Private',
		'Ящики с бонусами': 'BonusBoxes',
		'Золотые ящики': 'GoldBoxes',
		'Переодевание': 'ReArmor',
		'Автобаланс': 'AutoBalance',
		'Огонь по своим': 'FriendlyFire',
		'Припасы': 'Supplies',
		'Овердрайвы': 'Overdrives',
		'Зависимые припасы': 'DependentCooldown'
	};

	// === ЗНАЧАКИ ЗАВИСИМОСТИ ===
	const DEPENDENCIES = {
		'Supplies': ['DependentCooldown']
	};

	// === ФУНКЦИЯ СОЗДАНИЯ ЧЕКБОКСОВ ИЗ СПИСКА ===
	function createCustomCheckboxesFromMap() {
		window.__ACTIVE_CHECKBOXES__ = [];
		
		const originalContainer = document.querySelector('.css-1vafo3q');
		
		if (!originalContainer) {
			return;
		}
		
		
		const rowsGroup = document.createElement('div');
		rowsGroup.className = 'options-columns-wrapper';
		
		Object.entries(CHECKBOX_NAME_MAP).forEach(([russianName, englishName]) => {
			const newRow = document.createElement('div');
			newRow.className = 'custom-options-row';
			
			newRow.innerHTML = `
				<div class="custom-checkbox-replacement" data-name="${englishName}" data-has-img="false" data-disabled="${(englishName === 'DependentCooldown') ? true : false}">
					<span class="custom-checkbox-icon"></span>
				</div>
				<span class="custom-checkbox-label">${russianName}</span>
			`;
			
			const customCheckbox = newRow.querySelector('.custom-checkbox-replacement');
			
			// Определяем зависимый статус
			const isDependent = Object.keys(DEPENDENCIES).some(parent => 
				DEPENDENCIES[parent].includes(englishName)
			);
			
			const parentName = Object.keys(DEPENDENCIES).find(parent => 
				DEPENDENCIES[parent].includes(englishName)
			);
			
			// Добавляем клик
			customCheckbox.addEventListener('click', () => {
				// === БЛОКИРОВКА ЗАВИСИМЫХ ЧЕКБОКСОВ ===
				if (isDependent) {
					if (!window.__ACTIVE_CHECKBOXES__.includes('Supplies')) {
						// Запрещаем клик на зависимых если Припасы выключены
						return;
					}
				}
				
				// === ОБРАБОТКА РОДИТЕЛЬСКОГО ЧЕКБОКСА ===
				if (englishName === 'Supplies') {
					const currentChecked = customCheckbox.getAttribute('data-checked') === 'true';
					const newChecked = !currentChecked;
					
					customCheckbox.setAttribute('data-checked', newChecked.toString());
					const icon = customCheckbox.querySelector('.custom-checkbox-icon');
					icon.textContent = newChecked ? '✓' : '';
					
					updateActiveCheckboxes('Supplies', newChecked);
					
					if (newChecked) {
						const dependents = DEPENDENCIES['Supplies'];
						dependents.forEach(name => {
							const depElement = document.querySelector(`.custom-checkbox-replacement[data-name="${name}"]`);
							if (depElement) {
								depElement.setAttribute('data-disabled', 'false');
							}
						});
					} else {
						const dependents = DEPENDENCIES['Supplies'];
						dependents.forEach(name => {
							const depElement = document.querySelector(`.custom-checkbox-replacement[data-name="${name}"]`);
							if (depElement) {
								depElement.setAttribute('data-disabled', 'true');
								depElement.querySelector('.custom-checkbox-icon').textContent = '';
								updateActiveCheckboxes(name, false);
							}
						});
					}
					
					// Ничего не делаем с зависимыми — только проверяем доступность при клике
					return;
				}
				
				// === ОБРАБОТКА ДЕПЕНДЕНТОВ И ОСТАЛЬНЫХ ЧЕКБОКСОВ ===
				const currentChecked = customCheckbox.getAttribute('data-checked') === 'true';
				const newChecked = !currentChecked;
				
				customCheckbox.setAttribute('data-checked', newChecked.toString());
				const icon = customCheckbox.querySelector('.custom-checkbox-icon');
				icon.textContent = newChecked ? '✓' : '';
				
				updateActiveCheckboxes(englishName, newChecked);
			});
			
			rowsGroup.appendChild(newRow);
		});
		
		// Вставляем после оригинала
		originalContainer.parentElement.insertBefore(rowsGroup, originalContainer.nextSibling);
		
	}

	// === ОБНОВЛЕНИЕ ГЛОБАЛЬНОЙ ПЕРЕМЕННОЙ ===
	function updateActiveCheckboxes(name, isChecked) {
		if (isChecked) {
			if (!window.__ACTIVE_CHECKBOXES__.includes(name)) {
				window.__ACTIVE_CHECKBOXES__.push(name);
			}
		} else {
			window.__ACTIVE_CHECKBOXES__ = window.__ACTIVE_CHECKBOXES__.filter(n => n !== name);
		}

	}

	// === ЗАПУСК ===
	document.addEventListener('DOMContentLoaded', () => {
		setTimeout(() => {
			createCustomCheckboxesFromMap();
		}, 500);
	});

