	// 🔥 ОТДЕЛЬНАЯ ФУНКЦИЯ ДЛЯ АНИМАЦИИ (переиспользуемая)
	realWindow.triggerGlowAnimation = (element, duration = 500) => {
		if (!element) return;
		
		// Если анимация уже идёт — сбрасываем (чтобы перезапустить)
		if (element.dataset.glowing === 'true') {
			element.classList.remove('glow-on-update');
			// Небольшая задержка для перезапуска анимации
			setTimeout(() => startGlow(element), 10);
		} else {
			startGlow(element);
		}
		
		function startGlow(el) {
			el.classList.add('glow-on-update');
			el.dataset.glowing = 'true';
			
			// Убираем класс после завершения анимации
			const onEnd = () => {
				el.classList.remove('glow-on-update');
				el.dataset.glowing = 'false';
				el.removeEventListener('animationend', onEnd);
			};
			el.addEventListener('animationend', onEnd);
			
			// Фоллбэк: если animationend не сработает — таймаут
			setTimeout(() => {
				if (el.dataset.glowing === 'true') {
					el.classList.remove('glow-on-update');
					el.dataset.glowing = 'false';
				}
			}, duration + 100);
		}
	}
	
