	// 🔥 ОТДЕЛЬНАЯ ФУНКЦИЯ ДЛЯ АНИМАЦИИ (переиспользуемая)
	realWindow.triggerRankUpAnimation = (rankIndex, duration = 1000) => {
		const element = document.querySelector('.css-1irhnvq');
		if (!element) return;
		
		// 🔥 1. Запускаем анимацию свечения на элементе
		startRankUp(element);
		
		// 🔥 2. Показываем попап с поздравлением
		showRankUpPopup(rankIndex);
		
		function startRankUp(el) {
			el.classList.add('rank-on-update');
			el.dataset.rankUp = 'true';
			
			const onEnd = () => {
				el.classList.remove('rank-on-update');
				el.dataset.rankUp = 'false';
				el.removeEventListener('animationend', onEnd);
			};
			el.addEventListener('animationend', onEnd);
			
			setTimeout(() => {
				if (el.dataset.rankUp === 'true') {
					el.classList.remove('rank-on-update');
					el.dataset.rankUp = 'false';
				}
			}, duration + 100);
		}
	};
	
	// 🔥 НОВАЯ ФУНКЦИЯ: ПОКАЗ ПОПАПА
	function showRankUpPopup(rankIndex) {
		// Проверяем, не показан ли уже попап
		if (document.querySelector('.rank-up-popup-overlay')) {
			return;
		}
		
		if (!rankIndex) {
			return
		}
		
		// 🔍 Получаем название ранга (подставь свой массив или функцию)
		const rankName = rankNames[rankIndex - 1];
		
		// 🔍 Получаем URL иконки ранга из оригинального элемента
		const originalIcon = document.querySelector('img.css-1n25bb4');
		const rankIconUrl = originalIcon?.src;
		
		// 🔥 Создаём оверлей
		const overlay = document.createElement('div');
		overlay.className = 'rank-up-popup-overlay';
		
		// 🔥 Создаём контент попапа
		overlay.innerHTML = `
			<div class="rank-up-popup">
				<div class="rank-icon" style="background-image: url('${rankIconUrl}')"></div>
				<div class="popup-title">Поздравляем!</div>
				<div style="margin: 0.5rem 0;">
					<span class="popup-rank-name">Вы получили звание "${rankName}"</span>
				</div>
				<div class="popup-footer">
					Ваша награда в заданиях <br>
					во вкладке "Особые"
				</div>
			</div>
		`;
		
		// 🔥 Добавляем в DOM
		document.body.appendChild(overlay);
		
		// 🔥 Авто-удаление через 5 секунд с анимацией исчезновения
		setTimeout(() => {
			const popup = overlay.querySelector('.rank-up-popup');
			if (popup) {
				popup.style.animation = 'popup-fade-out 0.3s ease-in forwards';
			}
			
			// Удаляем оверлей после завершения анимации
			setTimeout(() => {
				if (overlay.parentNode) {
					overlay.parentNode.removeChild(overlay);
				}
			}, 300);
		}, 5000); // 5 секунд показа
		
	}
	
	// === ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ ДЛЯ БИТВЫ ===
	window.__BATTLE_FEED_CENTER__ = [];   // Центральные сообщения (10 сек)
	window.__BATTLE_FEED_RIGHT__ = [];     // Правые сообщения (30 сек)

	// === КОНФИГУРАЦИЯ ===
	const TOAST_CONFIG = {
		MAX_ITEMS: 10,           // Максимум элементов в интерфейсе
		CENTER_DURATION: 10000, // 10 секунд для центра
		RIGHT_DURATION: 30000  // 30 секунд для правой колонки
	};

	// === ПРОСТОЙ ДОБАВЛЕНИЕ ТОСТА (БЕЗ PROXY) ===
	function addBattleToast(queue, item) {
		const targetArray = queue === 'center' 
			? window.__BATTLE_FEED_CENTER__ 
			: window.__BATTLE_FEED_RIGHT__;
		
		const duration = queue === 'center' 
			? TOAST_CONFIG.CENTER_DURATION 
			: TOAST_CONFIG.RIGHT_DURATION;
		
		// 🔥 1. Если больше лимита — удаляем самый старый (FIFO)
		if (targetArray.length >= TOAST_CONFIG.MAX_ITEMS) {
			const oldest = targetArray.shift(); // Удаляем первый
			const container = document.getElementById(`toasts-container-${queue}`);
			const oldestEl = container?.querySelector('[data-toast-id]');
			if (oldestEl) removeToastElement(oldestEl);
		}
		
		// 🔥 2. Добавляем новый элемент с уникальным ID
		const toastId = `toast-${Date.now()}-${Math.random().toString(36).slice(2)}`;
		item.toastId = toastId;
		targetArray.push(item);
		
		// 🔥 3. Рендерим сразу (без подписок)
		renderSingleToast(queue, item, duration, toastId);
		
		// 🔥 4. Самоудаление через таймер
		setTimeout(() => {
			removeToastById(queue, toastId);
		}, duration);
	}

	
	// === РЕНДЕР ОДНОГО ТОСТА (МИНИМАЛЬНЫЙ) ===
	function renderSingleToast(queue, item, duration, toastId) {
		const containerId = `toasts-container-${queue}`;
		let container = document.getElementById(containerId);
		
		if (!container) {
			container = createToastContainer(queue);
		}
		
		const el = createBattleToastElement(item, queue);
		el.dataset.toastId = toastId;
		el.dataset.queue = queue;
		
		// Анимация появления
		el.style.opacity = '1';
		container.appendChild(el);
		
		setTimeout(() => {
			// Запуск анимации
			requestAnimationFrame(() => {
				el.style.transition = 'opacity 0.3s ease';
				el.style.opacity = '0.5';
			});
		}, queue === 'center' ? 3000 : 15000);
	}
	
	// === УДАЛЕНИЕ ПО ID ===
	function removeToastById(queue, toastId) {
		const container = document.getElementById(`toasts-container-${queue}`);
		if (!container) return;
		
		const el = container.querySelector(`[data-toast-id="${toastId}"]`);
		if (el) removeToastElement(el);
		
		// Чистим массив
		const targetArray = queue === 'center' 
			? window.__BATTLE_FEED_CENTER__ 
			: window.__BATTLE_FEED_RIGHT__;
		
		const index = targetArray.findIndex(t => t.toastId === toastId);
		if (index !== -1) {
			targetArray.splice(index, 1);
		}
	}

	// === УДАЛЕНИЕ ЭЛЕМЕНТА С АНИМАЦИЕЙ ===
	function removeToastElement(el) {
		if (!el?.parentNode) return;
		
		el.style.transition = 'opacity 0.3s ease';
		el.style.opacity = '0';
		
		setTimeout(() => {
			if (el?.parentNode) {
				el.parentNode.removeChild(el);
			}
		}, 300);
	}

	// === СОЗДАНИЕ КОНТЕЙНЕРА (ОДИН РАЗ) ===
	function createToastContainer(queue) {
		// Стили (если ещё не добавлены)
		if (!document.getElementById('toast-styles')) {
			const styles = document.createElement('style');
			styles.id = 'toast-styles';
			styles.textContent = `
				#toasts-container-center, #toasts-container-right {
					position: fixed;
					z-index: 1;
					display: flex;
					flex-direction: column;
					gap: 0.3rem;
					pointer-events: none; /* Не блокирует клики по игре */
				}
				#toasts-container-center {
					top: 4vh;
					left: 50%;
					transform: translateX(-50%);
					align-items: center;
					width: 100%;
				}
				#toasts-container-right {
					top: 4vh;
					right: 0.5rem;
					align-items: flex-end;
				}
				.battle-item {
					pointer-events: auto; /* Клик по тосту работает */
					will-change: opacity, transform; /* Оптимизация анимации */
				}
			`;
			document.head.appendChild(styles);
		}
		
		const container = document.createElement('div');
		container.id = `toasts-container-${queue}`;
		document.body.appendChild(container);
		return container;
	}
	
